def nullo(*args, default_ConsNull=list):
    """Create a goal asserting that one or more terms are a/the same `ConsNull` type."""

    def nullo_goal(s):
        nonlocal args, default_ConsNull

        args_rf = reify(args, s)
        arg_null_types = set(type(a) for a in args_rf if isinstance(a, ConsNull))

        if len(arg_null_types) == 1:
            null_type = arg_null_types.pop()
        else:
            null_type = default_ConsNull

        for arg in args_rf:
            if not isinstance(arg, null_type):
                return

        yield s

    return nullo_goal


def itero(l, default_ConsNull=list):
    """Construct a goal asserting that a term is an iterable type."""

    def itero_goal(S):
        nonlocal l, default_ConsNull
        l_rf = reify(l, S)

        c, d = var(), var()
        g = conde(
            [nullo(l_rf, default_ConsNull=default_ConsNull)],
            [conso(c, d, l_rf), itero(d, default_ConsNull=default_ConsNull)],
        )
        yield from g(S)

    return itero_goal


def permuteo(a, b, inner_eq=eq, no_ident=False):
    """Construct a goal asserting equality of sequences under permutation."""

    def permuteo_goal(S):
        nonlocal a, b, inner_eq, no_ident

        a_rf, b_rf = reify((a, b), S)

        # If lengths differ, fail
